source.chatCss:
:scope#bg1, :scope#bg_custom {
background-color: var(--cqs-canvas);
background-image:
linear-gradient(180deg, color-mix(in srgb, var(--cqs-headerA) 92%, transparent) 0%, transparent 46%),
radial-gradient(38% 16% at 18% 22%, color-mix(in srgb, var(--cqs-surface) 90%, transparent), transparent 70%),
radial-gradient(30% 13% at 78% 14%, color-mix(in srgb, var(--cqs-surface) 85%, transparent), transparent 70%),
radial-gradient(44% 18% at 62% 88%, color-mix(in srgb, var(--cqs-headerB) 90%, transparent), transparent 70%);
}
:scope #chat {
background: color-mix(in srgb, var(--cqs-surface) 58%, transparent);
backdrop-filter: blur(10px) saturate(1.1);
border-inline: 1px solid color-mix(in srgb, var(--cqs-surface) 75%, var(--cqs-border));
}
:scope[data-cqs-mode="flat"] #chat .mes {
background: linear-gradient(90deg, color-mix(in srgb, var(--cqs-surface) 88%, transparent), color-mix(in srgb, var(--cqs-surface) 55%, transparent));
border: 0;
border-left: 3px solid color-mix(in srgb, var(--cqs-accent) 55%, var(--cqs-border));
border-radius: 4px 16px 16px 4px;
margin: 8px 12px;
}
:scope[data-cqs-mode="flat"] #chat .mes[is_user="true"] {
background: linear-gradient(270deg, color-mix(in srgb, var(--cqs-user) 95%, transparent), color-mix(in srgb, var(--cqs-user) 45%, transparent));
border-left-color: var(--cqs-border);
}
:scope #chat .mes .ch_name .name_text { letter-spacing: .04em; font-weight: 700; }
:scope #chat .mes .avatar img { border-radius: 50%; box-shadow: 0 0 0 2px var(--cqs-surface), 0 4px 12px -6px var(--cqs-accent); }
:scope #chat .mes_text q { text-decoration: underline dotted color-mix(in srgb, var(--cqs-accent) 45%, transparent); text-underline-offset: 4px; }
:scope #chat .mes_text blockquote { border-left: 3px solid var(--cqs-accent); background: color-mix(in srgb, var(--cqs-accentSoft) 60%, transparent); border-radius: 0 12px 12px 0; }
:scope #send_form {
border: 1px solid color-mix(in srgb, var(--cqs-accent) 22%, var(--cqs-border));
border-radius: 18px;
background: color-mix(in srgb, var(--cqs-surface) 82%, transparent);
backdrop-filter: blur(12px);
box-shadow: 0 10px 30px -22px var(--cqs-accent), inset 0 1px 0 var(--cqs-surface);
}
:scope #send_form:focus-within { border-color: color-mix(in srgb, var(--cqs-accent) 55%, transparent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--cqs-accent) 14%, transparent), 0 10px 30px -22px var(--cqs-accent); }
:scope#options .options-content { border-radius: 16px; backdrop-filter: blur(12px); }

source.menuCss:
:scope#top-bar {
background: color-mix(in srgb, var(--cqs-surface) 80%, transparent);
backdrop-filter: blur(14px) saturate(1.15);
border-bottom: 0;
box-shadow: 0 10px 24px -20px var(--cqs-accent);
}
:scope#top-bar::after {
content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; pointer-events: none;
background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--cqs-accent) 55%, transparent) 30%, color-mix(in srgb, var(--cqs-headerB) 90%, var(--cqs-accent)) 70%, transparent);
}
:scope .drawer-icon { color: color-mix(in srgb, var(--cqs-accent) 40%, var(--cqs-muted)); }
:scope .drawer-icon:hover, :scope .drawer-icon.openIcon { color: var(--cqs-accent); }
:scope .drawer-content { background: color-mix(in srgb, var(--cqs-surface) 90%, transparent); backdrop-filter: blur(14px); border: 1px solid var(--cqs-border); border-radius: 18px; }
